namespace SmartSchool.Shared.Enums;

public enum NotificationSeverity
{
    Info = 1,
    Success = 2,
    Warning = 3,
    Critical = 4
}

public enum NotificationKind
{
    /// <summary>Sent by a person to selected users.</summary>
    Message = 1,

    /// <summary>Announcement to a whole tenant, school or the platform.</summary>
    Broadcast = 2,

    /// <summary>Generated by the system (homework set, results published…).</summary>
    System = 3
}

public enum AuditAction
{
    Created = 1,
    Updated = 2,
    Deleted = 3,
    SignedIn = 10,
    SignInFailed = 11,
    SignedOut = 12,
    Exported = 20
}

public enum StatusCategory
{
    Student = 1,
    Teacher = 2,
    Guardian = 3
}

/// <summary>Who a message is addressed to.</summary>
public enum AudienceType
{
    /// <summary>Hand-picked users.</summary>
    Users = 1,

    /// <summary>Everyone with given roles in the active school (or tenant).</summary>
    Roles = 2,

    /// <summary>Students and/or parents of one class.</summary>
    Class = 3,

    /// <summary>SuperAdmin only: every user of every tenant (optionally filtered by role).</summary>
    Platform = 4
}
